package com.diegonmarcos.cloudc3.pages

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.contentOrNull

/**
 * #1718 Infra > APIs > C3 Endpoints: the fleet services of the C3 environment (the other machines) with their public and mesh URLs,
 * read from the `fleet_endpoints` block of data/api_providers.json (text in, models out). That block is GENERATED by
 * data/gen_fleet_endpoints.py from ac_cloud-account/build.json::fleet_endpoints.services. These rows were Cloud C3 Webserver >
 * API's Public Endpoints page and the fleet group of its Mesh Endpoints page; the webserver shows only the phone now, and every
 * field it showed (id, kind, policy, health, public URL, mesh URL) is kept here with the ones it did not (source, auth, aliases,
 * route paths). Nothing here names a service; [group] is the id of the API group whose page draws the list.
 */
object FleetEndpoints {

    data class Service(
        val id: String, val kind: String, val policy: String, val health: String, val publicUrl: String?, val meshUrl: String?,
        val source: String, val auth: String, val aliases: List<String>, val routePaths: List<String>,
    )

    data class Decl(val group: String = "", val source: String = "", val services: List<Service> = emptyList()) {
        /** The services the webserver's Public Endpoints page listed: those with a public URL. */
        fun public(): List<Service> = services.filter { it.publicUrl != null }
        /** The services the fleet group of the webserver's Mesh Endpoints page listed: those with a mesh URL. */
        fun mesh(): List<Service> = services.filter { it.meshUrl != null }
        fun summary(): String = "${services.size} fleet services - ${public().size} public URLs - ${mesh().size} on the mesh"
    }

    private val json = Json { ignoreUnknownKeys = true; isLenient = true }

    /** Never throws: a missing or malformed block is an empty declaration. */
    fun parse(text: String): Decl {
        val root = runCatching { json.parseToJsonElement(text) }.getOrNull() as? JsonObject ?: return Decl()
        val block = root["fleet_endpoints"] as? JsonObject ?: return Decl()
        fun JsonObject.str(k: String) = (this[k] as? JsonPrimitive)?.contentOrNull
        fun JsonObject.strs(k: String) = (this[k] as? JsonArray).orEmpty().mapNotNull { (it as? JsonPrimitive)?.contentOrNull }
        val services = (block["services"] as? JsonArray).orEmpty().mapNotNull { it as? JsonObject }.mapNotNull { s ->
            val id = s.str("id")?.takeIf { it.isNotBlank() } ?: return@mapNotNull null
            Service(
                id = id, kind = s.str("kind").orEmpty(), policy = s.str("policy").orEmpty(), health = s.str("health").orEmpty(),
                publicUrl = s.str("public_url")?.takeIf { it.isNotBlank() }, meshUrl = s.str("mesh_url")?.takeIf { it.isNotBlank() },
                source = s.str("source").orEmpty(), auth = s.str("auth").orEmpty(), aliases = s.strs("aliases"), routePaths = s.strs("route_paths"),
            )
        }
        return Decl(block.str("group").orEmpty(), block.str("source").orEmpty(), services)
    }

    /** The lines one row draws, in order; every declared field appears, an absent one says so. */
    fun lines(s: Service): List<String> = listOf(
        "Public: ${s.publicUrl ?: "none (mesh only)"}",
        "Mesh: ${s.meshUrl ?: "none"}",
        "Health: ${s.health.ifBlank { "not declared" }}",
        "Auth: ${s.auth.ifBlank { "not declared" }}",
        s.aliases.takeIf { it.isNotEmpty() }?.let { "Aliases: ${it.joinToString(", ")}" }.orEmpty(),
        s.routePaths.takeIf { it.isNotEmpty() }?.let { "Routes: ${it.joinToString(", ")}" }.orEmpty(),
        s.source.takeIf { it.isNotBlank() }?.let { "Declared in: $it" }.orEmpty(),
    )

    fun links(s: Service): List<FleetModel.Link> =
        listOfNotNull(s.publicUrl?.let { FleetModel.Link("Public", it) }, s.meshUrl?.let { FleetModel.Link("Mesh", it) })
}
